package cn.xi.cloudwidget;
import android.app.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;

/** Border and icon contact sheets. All fixtures and old icon are debug-only. */
public class PolishQAActivity extends Activity {
    void save(Bitmap image,String name)throws Exception{File dir=new File(getFilesDir(),"review034");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
    Bitmap icon(int side,int mask){Bitmap image=Bitmap.createBitmap(side,side,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);Path path=new Path();if(mask==1)path.addCircle(side/2f,side/2f,side/2f,Path.Direction.CW);else if(mask==2)path.addRoundRect(0,0,side,side,side*.24f,side*.24f,Path.Direction.CW);else path.addRect(0,0,side,side,Path.Direction.CW);canvas.clipPath(path);Drawable drawable=getDrawable(mask==3?R.mipmap.ic_launcher:R.drawable.app_icon);drawable.setBounds(0,0,side,side);drawable.draw(canvas);return image;}
    void tile(LinearLayout row,Bitmap image,String label,int width,int height){LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setGravity(Gravity.CENTER);ImageView view=new ImageView(this);view.setImageBitmap(image);view.setScaleType(ImageView.ScaleType.FIT_CENTER);column.addView(view,new LinearLayout.LayoutParams(Ui.dp(this,width),Ui.dp(this,height)));TextView caption=Ui.text(this,label,12);caption.setGravity(Gravity.CENTER);column.addView(caption);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(Ui.dp(this,8),Ui.dp(this,6),Ui.dp(this,8),Ui.dp(this,8));row.addView(column,lp);}
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout body=Ui.column(this);body.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,12));Ui.root(this,body);try{if("icons".equals(getIntent().getStringExtra("mode"))){body.addView(Controls.heading(this,"v0.3.3 与 10 月 30 日新图标"));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);try(InputStream in=getAssets().open("qa/v033-icon.png")){tile(row,BitmapFactory.decodeStream(in),"v0.3.3",150,150);}Bitmap current=icon(512,0);save(current,"icon-vector-preview.png");tile(row,current,"10 月 30 日 SVG",150,150);body.addView(row);row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int mask=1;mask<=2;mask++){Bitmap image=icon(256,mask);save(image,mask==1?"icon-circle.png":"icon-rounded-square.png");tile(row,image,mask==1?"圆形裁切":"圆角方形裁切",130,130);}body.addView(row);row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int mask=1;mask<=2;mask++){Bitmap image=icon(Ui.dp(this,48),mask);save(image,"icon-48dp-"+mask+".png");tile(row,image,"48dp",48,48);}Bitmap adaptive=icon(256,3);save(adaptive,"icon-native-adaptive.png");tile(row,adaptive,"本机 adaptive",80,80);body.addView(row);}
        else {body.addView(Controls.heading(this,"边框快捷色 · 极细线约 1 px"));body.addView(Controls.hint(this,"样图 286 px，极细线默认粗细；最后一行对照旧色。"));int[] backgrounds={0xfffff2e3,0xffffffff,0xfff4dfe3,0xfffff2e3};String[] names={"奶油白","纯白","浅粉","旧色对照"};for(int n=0;n<4;n++){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int color=0;color<2;color++){Card card=new Card();card.type=3;card.background=backgrounds[n];card.border=1;card.borderWidth=1;card.borderInk=n==3?(color==0?0xffdce9f3:0xffdfe9dc):(color==0?Controls.BORDER_BLUE:Controls.BORDER_GREEN);card.body="今天也要好好生活";Bitmap image=Renderer.render(this,card,286,286,true);save(image,"border-"+n+"-"+color+".png");tile(row,image,names[n]+(color==0?" · 蓝":" · 绿"),164,164);}body.addView(row);}}
    }catch(Exception error){throw new IllegalStateException(error);}}
}
